#ifndef MINIVIDEO_SETTINGS_H
#define MINIVIDEO_SETTINGS_H
/* ************************************************************************** */

// "minivideo_settings.h.in" is the template file
// "minivideo_settings.h" is generated by CMake using the template file

// !!! EVERY TIMES CMake IS RUNNED, THIS FILE WILL BE REGENERATED !!!
// If QMake is used instead of CMake, this file will be leaved empty

#define minivideo_VERSION_MAJOR 0
#define minivideo_VERSION_MINOR 15
#define minivideo_VERSION_PATCH 0

#define ENABLE_DEBUG            1              //!< Toggle debug and trace output
#define ENABLE_COLORS           ON             //!< Toggle colored terminal output

#define ENABLE_STB_IMAGE        ON          //!< Toggle bundled stb_image support
#define ENABLE_STB_IMAGE_WRITE  ON    //!< Toggle bundled stb_image_write support
#define ENABLE_AVIF             OFF               //!< Toggle external libwebp support
#define ENABLE_WEBP             OFF               //!< Toggle external libwebp support
#define ENABLE_JPEG             OFF               //!< Toggle external libjpeg support
#define ENABLE_PNG              OFF                //!< Toggle external libpng support

#define ENABLE_MEMFD            ON              //!< Enable memfd support for Linux

/* ************************************************************************** */
#endif // MINIVIDEO_SETTINGS_H
